SELECT valid AS time,
       if(skyc1 = 'FEW', skyl1, NULL) AS `◔ FEW`,
       if(skyc1 = 'SCT', skyl1, NULL) AS `◑ SCT`,
       if(skyc1 = 'BKN', skyl1, NULL) AS `◕ BKN`,
       if(skyc1 = 'OVC', skyl1, NULL) AS `● OVC`,
       if(skyc1 = 'VV', skyl1, NULL) AS `⊗ VV`,
       if(skyc2 = 'FEW', skyl2, NULL) AS `◔ FEW (layer 2)`,
       if(skyc2 = 'SCT', skyl2, NULL) AS `◑ SCT (layer 2)`,
       if(skyc2 = 'BKN', skyl2, NULL) AS `◕ BKN (layer 2)`,
       if(skyc2 = 'OVC', skyl2, NULL) AS `● OVC (layer 2)`,
       if(skyc2 = 'VV', skyl2, NULL) AS `⊗ VV (layer 2)`,
       if(skyc3 = 'FEW', skyl3, NULL) AS `◔ FEW (layer 3)`,
       if(skyc3 = 'SCT', skyl3, NULL) AS `◑ SCT (layer 3)`,
       if(skyc3 = 'BKN', skyl3, NULL) AS `◕ BKN (layer 3)`,
       if(skyc3 = 'OVC', skyl3, NULL) AS `● OVC (layer 3)`,
       if(skyc3 = 'VV', skyl3, NULL) AS `⊗ VV (layer 3)`,
       if(skyc4 = 'FEW', skyl4, NULL) AS `◔ FEW (layer 4)`,
       if(skyc4 = 'SCT', skyl4, NULL) AS `◑ SCT (layer 4)`,
       if(skyc4 = 'BKN', skyl4, NULL) AS `◕ BKN (layer 4)`,
       if(skyc4 = 'OVC', skyl4, NULL) AS `● OVC (layer 4)`,
       if(skyc4 = 'VV', skyl4, NULL) AS `⊗ VV (layer 4)`
FROM faa.weather FINAL WHERE station = '${station}' AND $__timeFilter(valid) ORDER BY time

